	hookAgent, ok := agent.AsHookSupport(ag)
	if !ok {
		t.Fatal("Codex agent does not support hooks")
	}
	if _, err := hookAgent.InstallHooks(context.Background(), false); err != nil {
		t.Fatalf("install Codex hooks: %v", err)
	}
}

